hardware/float.sl.content:
// Arbitrary-precision floating point as shapes.
//
// A float is three shapes connected:
//   sign:     1 bit (0 = positive, 1 = negative)
//   mantissa: N-byte integer (arbitrary precision)
//   exponent: M-byte signed integer (arbitrary range)
//
// value = (-1)^sign * mantissa * 2^exponent
//
// No IEEE 754. No fixed width. Precision is a parameter of the shape.
// The operations are structural: subgraphs of integer operations
// with exponent alignment.

shape hardware.float : hardware.math {
  type: structure
  layer: 3
  deps: [hardware.math.add, hardware.math.sub, hardware.math.mul, hardware.math.div, hardware.math.shift, hardware.math.compare]
  """
// Float representation:
//   bytes 0..N-1:   mantissa (big integer, unsigned)
//   bytes N..N+M-1: exponent (signed integer)
//   byte  N+M:      sign (0 or 1)
//   byte  N+M+1:    mantissa width N
//   byte  N+M+2:    exponent width M
//
// Default: N=4, M=2 (32-bit mantissa, 16-bit exponent range).
// Can grow to any size.

fn float_new(mantissa_width, exponent_width) {
  let total = mantissa_width + exponent_width + 3
  let buf = bytes(total)
  set buf = byte_set(buf, mantissa_width + exponent_width + 1, mantissa_width)
  set buf = byte_set(buf, mantissa_width + exponent_width + 2, exponent_width)
  buf
}

fn float_from_int(n, precision) {
  let f = float_new(precision, 2)
  // Store integer as mantissa with exponent 0.
  let mw = precision
  for i in range(mw) {
    set f = byte_set(f, i, bit_and(bit_shr(n, i * 8), 0xFF))
  }
  // Sign.
  if n < 0 {
    set f = byte_set(f, mw + 2, 1)
    // Negate mantissa.
    let carry = 1
    for i in range(mw) {
      let v = bit_xor(byte_get(f, i), 0xFF) + carry
      set f = byte_set(f, i, bit_and(v, 0xFF))
      set carry = bit_shr(v, 8)
    }
  }
  f
}
"""
}

shape hardware.float.add : hardware.float {
  type: gate
  layer: 3
  """
// Float addition: align exponents, then add mantissas.
//
// 1. Compare exponents. Shift the smaller-exponent mantissa right
//    by the difference.
// 2. Add mantissas (handling signs).
// 3. Normalize: shift mantissa until leading bit is set, adjust exponent.
//
// Gates: exponent compare (2M) + mantissa shift (N*log2(N)) +
//        mantissa add (N) + normalize (N*log2(N)) = O(N*log2(N)).
fn float_add(a, b) {
  let mw_a = byte_get(a, len(a) - 2)
  let mw_b = byte_get(b, len(b) - 2)
  let ew_a = byte_get(a, len(a) - 1)

  // Extract exponents.
  let exp_a = 0
  for i in range(ew_a) {
    set exp_a = exp_a + bit_shl(byte_get(a, mw_a + i), i * 8)
  }
  let exp_b = 0
  for i in range(ew_a) {
    set exp_b = exp_b + bit_shl(byte_get(b, mw_b + i), i * 8)
  }

  // Align: shift mantissa of smaller exponent right.
  let shift = abs(exp_a - exp_b)
  // After alignment, add mantissas using integer add.
  // Result exponent = max(exp_a, exp_b).
  // Sign handling: if signs differ, subtract instead.
  let sign_a = byte_get(a, mw_a + ew_a)
  let sign_b = byte_get(b, mw_b + ew_a)

  if sign_a == sign_b {
    // Same sign: add mantissas, keep sign.
    auto "add mantissas"
  } else {
    // Different sign: subtract smaller from larger, keep larger's sign.
    auto "subtract mantissas"
  }
}
"""
}

shape hardware.float.mul : hardware.float {
  type: gate
  layer: 3
  """
// Float multiplication: multiply mantissas, add exponents.
//
// result.mantissa = a.mantissa * b.mantissa
// result.exponent = a.exponent + b.exponent
// result.sign = a.sign XOR b.sign
//
// Gates: mantissa mul (N^2) + exponent add (M) + sign XOR (1).
// This is why multiplication is more expensive than addition.
fn float_mul(a, b) {
  // Sign: XOR.
  let mw = byte_get(a, len(a) - 2)
  let ew = byte_get(a, len(a) - 1)
  let sign = bit_xor(byte_get(a, mw + ew), byte_get(b, mw + ew))

  // Exponent: add.
  // Mantissa: integer multiply (shift-and-add subgraph).
  // Normalize result.
  auto "mul"
}
"""
}

shape hardware.float.div : hardware.float {
  type: gate
  layer: 3
  """
// Float division: divide mantissas, subtract exponents.
//
// result.mantissa = a.mantissa / b.mantissa
// result.exponent = a.exponent - b.exponent
// result.sign = a.sign XOR b.sign
//
// Gates: mantissa div (N^2) + exponent sub (M) + sign XOR (1).
fn float_div(a, b) {
  auto "div"
}
"""
}

hardware/compile.sl.content:
shape hardware.compile : hardware {
  type: exec
  layer: 3
  desc: "Project shapes to Verilog"
  """
// hardware.compile -- project shape graph onto Verilog gate lattice.
//
// Usage: run hardware.compile
//   or from shell: compile-hw [output.v]
//
// The projection:
//   Shape.ID        -> gate index (sorted by ID for locality)
//   Shape.Character -> transform_cfg (content hash -> LUT truth table)
//   Shape.Structure -> connection matrix (deps -> wave_in routing)
//   Shape.Tick      -> initial tick value
//
// Output: Verilog module that instantiates shape_lattice with full config.

let all = sort_list(shapes_under(""))
let n = len(all)
let cols = ceil(pow(n, 0.5))
let rows = ceil(n / cols)
let num_gates = rows * cols
let cw = 8
let tw = 16
let max_deps = 4

// Header
print("// Generated by hardware.compile: shape-lang -> Verilog projection.")
print("// " + n + " shapes mapped to " + rows + "x" + cols + " lattice (" + num_gates + " gates).")
print("//")
print("// Shape placement (gate index -> shape ID):")
let idx = 0
for id in all {
  print("//   [" + pad_left(to_string(idx), 3) + "] " + id)
  set idx = idx + 1
}
print("")

// Module declaration
let idx_width = ceil(pow(num_gates + 1, 0.5))
if idx_width < 1 {
  set idx_width = 1
}
// Compute log2 ceiling for index width
set idx_width = 1
let temp = num_gates
while temp > 1 {
  set idx_width = idx_width + 1
  set temp = ceil(temp / 2)
}

print("module shape_os (")
print("    input  wire clk,")
print("    input  wire rst,")
print("    input  wire                     ext_wave,")
print("    input  wire [" + (idx_width - 1) + ":0] ext_target,")
print("    input  wire [" + (cw - 1) + ":0] ext_data,")
print("    output wire [" + (num_gates - 1) + ":0] all_coherent,")
print("    output wire [" + (num_gates - 1) + ":0] all_wave_out")
print(");")
print("")

// Parameters
print("    localparam ROWS          = " + rows + ";")
print("    localparam COLS          = " + cols + ";")
print("    localparam CONTENT_WIDTH = " + cw + ";")
print("    localparam TICK_WIDTH    = " + tw + ";")
print("    localparam MAX_DEPS      = " + max_deps + ";")
print("    localparam NUM_GATES     = " + num_gates + ";")
print("    localparam IDX_WIDTH     = " + idx_width + ";")
print("")

// Transform configs
print("    wire [NUM_GATES*CONTENT_WIDTH-1:0] transform_cfgs;")
set idx = 0
for id in all {
  let c = content(id)
  // Hash content to cw bits using shape_tick as proxy
  let hash = mod(tick(id) * 31 + len(c) * 7, 256)
  let hi = (idx + 1) * cw - 1
  let lo = idx * cw
  print("    assign transform_cfgs[" + hi + ":" + lo + "] = " + cw + "'h" + hash + "; // " + id)
  set idx = idx + 1
}
// Fill unused gates
while idx < num_gates {
  let hi = (idx + 1) * cw - 1
  let lo = idx * cw
  print("    assign transform_cfgs[" + hi + ":" + lo + "] = " + cw + "'h0; // unused")
  set idx = idx + 1
}
print("")

// Connection matrix
print("    wire [NUM_GATES*MAX_DEPS*IDX_WIDTH-1:0] connections;")

// Build index lookup
let gate_map = map_new()
set idx = 0
for id in all {
  set gate_map = map_set(gate_map, id, idx)
  set idx = idx + 1
}

set idx = 0
for id in all {
  let dp = deps(id)
  let dep_indices = []
  for dep in dp {
    if map_has(gate_map, dep) {
      set dep_indices = append(dep_indices, map_get(gate_map, dep))
    }
  }
  // Also add parent as implicit dep
  let p = parent(id)
  if p != "" {
    if map_has(gate_map, p) {
      let pi = map_get(gate_map, p)
      if !(pi in dep_indices) {
        set dep_indices = append(dep_indices, pi)
      }
    }
  }
  // Pad to max_deps with num_gates (no connection)
  while len(dep_indices) < max_deps {
    set dep_indices = append(dep_indices, num_gates)
  }
  for d in range(max_deps) {
    let lo = (idx * max_deps + d) * idx_width
    let hi = lo + idx_width - 1
    let src = index(dep_indices, d)
    let comment = ""
    if src < n {
      set comment = " // " + id + " -> " + index(all, src)
    }
    print("    assign connections[" + hi + ":" + lo + "] = " + idx_width + "'d" + src + ";" + comment)
  }
  set idx = idx + 1
}
// Fill unused gate connections
while idx < num_gates {
  for d in range(max_deps) {
    let lo = (idx * max_deps + d) * idx_width
    let hi = lo + idx_width - 1
    print("    assign connections[" + hi + ":" + lo + "] = " + idx_width + "'d" + num_gates + ";")
  }
  set idx = idx + 1
}
print("")

// Lattice wires and instantiation
print("    wire [NUM_GATES*CONTENT_WIDTH-1:0] lattice_content;")
print("    wire [NUM_GATES*TICK_WIDTH-1:0]    lattice_ticks;")
print("")
print("    shape_lattice #(")
print("        .ROWS(ROWS),")
print("        .COLS(COLS),")
print("        .CONTENT_WIDTH(CONTENT_WIDTH),")
print("        .TICK_WIDTH(TICK_WIDTH),")
print("        .MAX_DEPS(MAX_DEPS)")
print("    ) lattice (")
print("        .clk(clk),")
print("        .rst(rst),")
print("        .ext_wave(ext_wave),")
print("        .ext_target(ext_target),")
print("        .ext_data(ext_data),")
print("        .transform_cfgs(transform_cfgs),")
print("        .connections(connections),")
print("        .all_content(lattice_content),")
print("        .all_ticks(lattice_ticks),")
print("        .all_coherent(all_coherent),")
print("        .all_wave_out(all_wave_out)")
print("    );")
print("")
print("endmodule")
"""
}

hardware/math.sl.content:
// Integer arithmetic as shape subgraphs.
//
// All math derives from add and shift. Multiply is repeated add.
// Divide is repeated subtract. These ARE the gate subgraphs.
// No FPU needed. The math IS the lattice.

shape hardware.math : hardware {
  type: axiom
  layer: 0
  "Arithmetic from persistence. Add is the minimal change operation: two shapes combine to produce a third that persists."
}

shape hardware.math.add : hardware.math {
  type: gate
  layer: 1
  width: 8
  """
// Ripple-carry adder: N shape-gates in series.
// Gate i: full_adder(a[i], b[i], carry_in) -> (sum[i], carry_out)
// carry_out of gate i connects to carry_in of gate i+1.
// Total gates: N (one per bit).
// Propagation delay: N gate delays (carry chain).
//
// For width W: W gates, W cycles to complete.
fn add(a, b) {
  let carry = 0
  let result = bytes(len(a))
  for i in range(len(a)) {
    let s = byte_get(a, i) + byte_get(b, i) + carry
    set result = byte_set(result, i, bit_and(s, 0xFF))
    set carry = bit_shr(s, 8)
  }
  result
}
"""
}

shape hardware.math.sub : hardware.math {
  type: gate
  layer: 1
  deps: [hardware.math.add]
  """
// Subtraction: add with two's complement.
// Negate b (invert + add 1), then add.
// Gates: N (invert) + N (add) + N (add with a) = 3N.
fn sub(a, b) {
  let neg_b = bytes(len(b))
  let carry = 1
  for i in range(len(b)) {
    let inv = bit_xor(byte_get(b, i), 0xFF)
    let s = inv + carry
    set neg_b = byte_set(neg_b, i, bit_and(s, 0xFF))
    set carry = bit_shr(s, 8)
  }
  add(a, neg_b)
}
"""
}

shape hardware.math.shift : hardware.math {
  type: gate
  layer: 1
  """
// Barrel shifter: log2(N) layers of muxes.
// Each layer shifts by 2^k if the k-th bit of the shift amount is set.
// Gates: N * log2(N) (mux per bit per layer).
fn shl(a, n) {
  let result = a
  let shift = n
  let bit = 1
  while bit <= shift {
    if bit_and(shift, bit) != 0 {
      set result = bytes_concat(bytes(bit), bytes_slice(result, 0, len(result) - bit))
    }
    set bit = bit * 2
  }
  result
}
"""
}

shape hardware.math.mul : hardware.math {
  type: gate
  layer: 2
  deps: [hardware.math.add, hardware.math.shift]
  """
// Multiply: shift-and-add.
// For each bit of b that is set, shift a left by that bit position
// and add to accumulator.
// Gates: N * (N shift + N add) = O(N^2).
// On the lattice: N parallel shift subgraphs feeding N adders.
fn mul(a, b) {
  let acc = bytes(len(a) + len(b))
  for i in range(len(b) * 8) {
    if bit_and(byte_get(b, i / 8), bit_shl(1, mod(i, 8))) != 0 {
      let shifted = shl(a, i)
      set acc = add(acc, shifted)
    }
  }
  acc
}
"""
}

shape hardware.math.div : hardware.math {
  type: gate
  layer: 2
  deps: [hardware.math.sub, hardware.math.shift]
  """
// Division: long division via repeated subtraction with shifting.
// For each bit position from high to low:
//   if remainder >= (divisor << bit), subtract and set quotient bit.
// Gates: O(N^2) (N iterations, each with compare + subtract).
fn div(a, b) {
  let quotient = bytes(len(a))
  let remainder = a
  for i in range(len(a) * 8 - 1, -1) {
    let shifted = shl(b, i)
    // Compare: try subtract, check if result is non-negative.
    let diff = sub(remainder, shifted)
    if byte_get(diff, len(diff) - 1) < 128 {
      // Non-negative: divisor fits.
      set remainder = diff
      let byte_idx = i / 8
      let bit_idx = mod(i, 8)
      set quotient = byte_set(quotient, byte_idx,
        bit_or(byte_get(quotient, byte_idx), bit_shl(1, bit_idx)))
    }
  }
  quotient
}
"""
}

shape hardware.math.compare : hardware.math {
  type: gate
  layer: 1
  deps: [hardware.math.sub]
  """
// Compare: subtract and check sign bit.
// a < b  iff  (a - b) has sign bit set.
// a == b iff  (a - b) == 0.
// Gates: N (subtract) + N (zero check) = 2N.
fn compare(a, b) {
  let diff = sub(a, b)
  let sign = bit_and(byte_get(diff, len(diff) - 1), 128)
  let zero = 1
  for i in range(len(diff)) {
    if byte_get(diff, i) != 0 {
      set zero = 0
    }
  }
  // Returns: -1 if a < b, 0 if a == b, 1 if a > b.
  if zero == 1 { 0 }
  else if sign != 0 { -1 }
  else { 1 }
}
"""
}

