law/persistence.sl.content:
shape law.persistence : law {
  type: law
  layer: 0
  """
// Law 0: A shape persists stably only if its structure is coherent.
// Incoherent shapes dissolve. This is the axiom.
//
// The engine implements this as: validate() checks all shapes,
// edit() propagates waves to maintain coherence after mutation,
// the store persists only what the engine holds.
//
// On a shape machine, this law IS the persistence mechanism.
// In emulation, engine.validate + engine.store implement it.
fn check_persistence(id) {
  if !exists(id) {
    absorb
  }
  let dp = deps(id)
  for dep in dp {
    if !exists(dep) {
      flag
    }
  }
  auto "persists"
}
"""
}

law/consistency.sl.content:
shape law.consistency : law {
  type: law
  layer: 0
  """
// Law 3: Coupled incompatible shapes must resolve or trigger dissolution.
// Contradictions in contact cannot persist. The engine resolves this
// through block (withdraw permission) and propagation (force resolution).
//
// engine.block implements this: when an author is blocked, existing
// shapes persist (Law 2) but get flagged with content warnings.
// The wave propagates the inconsistency until it resolves.
fn check_consistency(id) {
  let dt = dependents(id)
  for dep in dt {
    let w = dim(dep, "warning")
    if w != "" {
      flag
    }
  }
  auto "consistent"
}
"""
}

law/conservation.sl.content:
shape law.conservation : law {
  type: law
  layer: 0
  """
// Law 2: No structure from nothing, no destruction into nothing.
// You cannot remove a shape that others depend on.
// You cannot create a shape without the system recording it.
// Every mutation advances the tick. Every change is traced.
//
// engine.trace implements conservation of history.
// rm checks dependents before allowing removal.
fn check_conservation(id) {
  if !exists(id) {
    flag
  }
  auto "conserved"
}
"""
}

law/reference.sl.content:
shape law.reference : law {
  type: law
  layer: 0
  """
// Law 1: References must close, point to invariants, or be bounded.
// Dangling references are incoherent. The engine tracks all deps
// and validates reference closure.
//
// engine.propagate implements this: when a shape changes, the wave
// follows references to maintain closure. Dependents must respond.
fn check_reference(id) {
  let dp = deps(id)
  for dep in dp {
    if !exists(dep) {
      flag
    }
  }
  auto "references close"
}
"""
}

lib/base64.sl.content:
shape lib.base64 : lib {
  type: lib
  layer: 3
  """
// Base64 encode/decode — pure shape-lang on byte primitives.
// Standard base64 alphabet (RFC 4648).

fn _b64_char(n) {
  if n < 26 { auto chr(n + 65) }
  if n < 52 { auto chr(n - 26 + 97) }
  if n < 62 { auto chr(n - 52 + 48) }
  if n == 62 { auto "+" }
  auto "/"
}

fn _b64_val(c) {
  let n = ord(c)
  if n >= 65 { if n <= 90 { auto n - 65 } }
  if n >= 97 { if n <= 122 { auto n - 97 + 26 } }
  if n >= 48 { if n <= 57 { auto n - 48 + 52 } }
  if c == "+" { auto 62 }
  if c == "/" { auto 63 }
  auto 0
}

fn base64_encode(buf) {
  let n = len(buf)
  let out = ""
  let i = 0
  while i < n {
    let b0 = byte_get(buf, i)
    let b1 = 0
    let b2 = 0
    if i + 1 < n { let b1 = byte_get(buf, i + 1) }
    if i + 2 < n { let b2 = byte_get(buf, i + 2) }
    let out = out + _b64_char(bit_shr(b0, 2))
    let out = out + _b64_char(bit_or(bit_shl(bit_and(b0, 3), 4), bit_shr(b1, 4)))
    if i + 1 < n {
      let out = out + _b64_char(bit_or(bit_shl(bit_and(b1, 0x0F), 2), bit_shr(b2, 6)))
    }
    if i + 1 >= n { let out = out + "=" }
    if i + 2 < n {
      let out = out + _b64_char(bit_and(b2, 0x3F))
    }
    if i + 2 >= n { let out = out + "=" }
    let i = i + 3
  }
  auto out
}

fn base64_decode(s) {
  let n = len(s)
  let out = bytes(0)
  let i = 0
  while i < n {
    let c0 = at(s, i)
    let c1 = at(s, i + 1)
    let c2 = at(s, i + 2)
    let c3 = at(s, i + 3)
    let v0 = _b64_val(c0)
    let v1 = _b64_val(c1)
    let b0 = bit_or(bit_shl(v0, 2), bit_shr(v1, 4))
    let out = bytes_concat(out, bytes_from([b0]))
    if c2 != "=" {
      let v2 = _b64_val(c2)
      let b1 = bit_and(bit_or(bit_shl(v1, 4), bit_shr(v2, 2)), 0xFF)
      let out = bytes_concat(out, bytes_from([b1]))
      if c3 != "=" {
        let v3 = _b64_val(c3)
        let b2 = bit_and(bit_or(bit_shl(v2, 6), v3), 0xFF)
        let out = bytes_concat(out, bytes_from([b2]))
      }
    }
    let i = i + 4
  }
  auto out
}

fn base64_encode_string(s) {
  auto base64_encode(string_to_bytes(s))
}

fn base64_decode_string(s) {
  auto bytes_to_string(base64_decode(s))
}
"""
}

lib/pdf.sl.content:
shape lib.pdf : lib {
  type: lib
  layer: 3
  """
// PDF generation — pure shape-lang. Mostly string building with offset tracking.

fn _pdf_escape(text) {
  let out = ""
  let i = 0
  while i < len(text) {
    let c = at(text, i)
    let i = i + 1
    if c == "\\" { let out = out + "\\\\" }
    if c == "(" { let out = out + "\\(" }
    if c == ")" { let out = out + "\\)" }
    if c != "\\" {
      if c != "(" {
        if c != ")" {
          let out = out + c
        }
      }
    }
  }
  auto out
}

fn _pad10(n) {
  let s = to_string(n)
  while len(s) < 10 { let s = "0" + s }
  auto s
}

fn pdf_create(blocks) {
  // blocks = [[type, text], ...] where type is "heading" or "paragraph".
  // Returns bytes (the PDF file).
  let stream = "BT\n/F1 12 Tf\n"
  let y = 750
  let i = 0
  while i < len(blocks) {
    let block = at(blocks, i)
    let i = i + 1
    let btype = at(block, 0)
    let text = at(block, 1)
    let font_size = 12
    if btype == "heading" { let font_size = 24 }
    let stream = stream + "/F1 " + to_string(font_size) + " Tf\n"
    let stream = stream + "1 0 0 1 72 " + to_string(y) + " Tm\n(" + _pdf_escape(text) + ") Tj\n"
    let y = y - font_size - 6
    if y < 72 { break }
  }
  let stream = stream + "ET\n"
  let stream_len = len(stream)
  let pdf = "%PDF-1.4\n"
  let off1 = len(pdf)
  let pdf = pdf + "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"
  let off2 = len(pdf)
  let pdf = pdf + "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n"
  let off3 = len(pdf)
  let pdf = pdf + "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>\nendobj\n"
  let off4 = len(pdf)
  let pdf = pdf + "4 0 obj\n<< /Length " + to_string(stream_len) + " >>\nstream\n" + stream + "\nendstream\nendobj\n"
  let off5 = len(pdf)
  let pdf = pdf + "5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n"
  let xref_off = len(pdf)
  let pdf = pdf + "xref\n0 6\n0000000000 65535 f \n"
  let pdf = pdf + _pad10(off1) + " 00000 n \n"
  let pdf = pdf + _pad10(off2) + " 00000 n \n"
  let pdf = pdf + _pad10(off3) + " 00000 n \n"
  let pdf = pdf + _pad10(off4) + " 00000 n \n"
  let pdf = pdf + _pad10(off5) + " 00000 n \n"
  let pdf = pdf + "trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n" + to_string(xref_off) + "\n%%EOF\n"
  auto string_to_bytes(pdf)
}
"""
}

