  layer: 3
  """
// XML text escaping — pure shape-lang.

fn xml_escape(s) {
  let out = ""
  let i = 0
  let n = len(s)
  while i < n {
    let c = at(s, i)
    let i = i + 1
    if c == "&" { let out = out + "&amp;" }
    if c == "<" { let out = out + "&lt;" }
    if c == ">" { let out = out + "&gt;" }
    if c == "\"" { let out = out + "&quot;" }
    if c == "'" { let out = out + "&#39;" }
    if c != "&" {
      if c != "<" {
        if c != ">" {
          if c != "\"" {
            if c != "'" {
              let out = out + c
            }
          }
        }
      }
    }
  }
  auto out
}
"""
}

lib/zip.sl.content:
shape lib.zip : lib {
  type: lib
  layer: 3
  """
// ZIP format — pure shape-lang on byte primitives.
// Uses Store method (no compression). XLSX/DOCX work fine uncompressed.

fn _zip_local_header(name, data) {
  // Local file header: signature + version + flags + method + time + date +
  // crc32 + compressed size + uncompressed size + name len + extra len + name
  let name_bytes = string_to_bytes(name)
  let name_len = len(name_bytes)
  let data_len = len(data)
  let crc = crc32(data)
  let hdr = bytes(30)
  let hdr = write_u32_le(hdr, 0, 0x04034b50)
  let hdr = write_u16_le(hdr, 4, 20)
  let hdr = write_u16_le(hdr, 6, 0)
  let hdr = write_u16_le(hdr, 8, 0)
  let hdr = write_u16_le(hdr, 10, 0)
  let hdr = write_u16_le(hdr, 12, 0)
  let hdr = write_u32_le(hdr, 14, crc)
  let hdr = write_u32_le(hdr, 18, data_len)
  let hdr = write_u32_le(hdr, 22, data_len)
  let hdr = write_u16_le(hdr, 26, name_len)
  let hdr = write_u16_le(hdr, 28, 0)
  auto bytes_concat(bytes_concat(hdr, name_bytes), data)
}

fn _zip_central_entry(name, data, local_offset) {
  let name_bytes = string_to_bytes(name)
  let name_len = len(name_bytes)
  let data_len = len(data)
  let crc = crc32(data)
  let hdr = bytes(46)
  let hdr = write_u32_le(hdr, 0, 0x02014b50)
  let hdr = write_u16_le(hdr, 4, 20)
  let hdr = write_u16_le(hdr, 6, 20)
  let hdr = write_u16_le(hdr, 8, 0)
  let hdr = write_u16_le(hdr, 10, 0)
  let hdr = write_u16_le(hdr, 12, 0)
  let hdr = write_u16_le(hdr, 14, 0)
  let hdr = write_u32_le(hdr, 16, crc)
  let hdr = write_u32_le(hdr, 20, data_len)
  let hdr = write_u32_le(hdr, 24, data_len)
  let hdr = write_u16_le(hdr, 28, name_len)
  let hdr = write_u16_le(hdr, 30, 0)
  let hdr = write_u16_le(hdr, 32, 0)
  let hdr = write_u16_le(hdr, 34, 0)
  let hdr = write_u16_le(hdr, 36, 0)
  let hdr = write_u32_le(hdr, 38, 0)
  let hdr = write_u32_le(hdr, 42, local_offset)
  auto bytes_concat(hdr, name_bytes)
}

fn zip_create(entries) {
  // entries = [[name, content_string], ...]
  // Returns bytes (the ZIP file).
  let body = bytes(0)
  let central = bytes(0)
  let count = 0
  let i = 0
  while i < len(entries) {
    let entry = at(entries, i)
    let i = i + 1
    let name = at(entry, 0)
    let content = at(entry, 1)
    let data = string_to_bytes(content)
    let offset = len(body)
    let local = _zip_local_header(name, data)
    let body = bytes_concat(body, local)
    let centry = _zip_central_entry(name, data, offset)
    let central = bytes_concat(central, centry)
    let count = count + 1
  }
  let central_offset = len(body)
  let central_size = len(central)
  // End of central directory record
  let eocd = bytes(22)
  let eocd = write_u32_le(eocd, 0, 0x06054b50)
  let eocd = write_u16_le(eocd, 4, 0)
  let eocd = write_u16_le(eocd, 6, 0)
  let eocd = write_u16_le(eocd, 8, count)
  let eocd = write_u16_le(eocd, 10, count)
  let eocd = write_u32_le(eocd, 12, central_size)
  let eocd = write_u32_le(eocd, 16, central_offset)
  let eocd = write_u16_le(eocd, 20, 0)
  auto bytes_concat(bytes_concat(body, central), eocd)
}

fn zip_extract(buf) {
  // Parse ZIP, return [[name, content_string], ...]
  // Find end-of-central-directory (last 22+ bytes).
  let blen = len(buf)
  let eocd_off = blen - 22
  // Scan backward for EOCD signature.
  while eocd_off >= 0 {
    if read_u32_le(buf, eocd_off) == 0x06054b50 { break }
    let eocd_off = eocd_off - 1
  }
  if eocd_off < 0 { auto [] }
  let count = read_u16_le(buf, eocd_off + 8)
  let cd_offset = read_u32_le(buf, eocd_off + 16)
  let entries = []
  let off = cd_offset
  let i = 0
  while i < count {
    let i = i + 1
    if read_u32_le(buf, off) != 0x02014b50 { break }
    let comp_size = read_u32_le(buf, off + 20)
    let uncomp_size = read_u32_le(buf, off + 24)
    let name_len = read_u16_le(buf, off + 28)
    let extra_len = read_u16_le(buf, off + 30)
    let comment_len = read_u16_le(buf, off + 32)
    let local_offset = read_u32_le(buf, off + 42)
    let name = bytes_to_string(bytes_slice(buf, off + 46, off + 46 + name_len))
    // Read data from local file header.
    let local_name_len = read_u16_le(buf, local_offset + 26)
    let local_extra_len = read_u16_le(buf, local_offset + 28)
    let data_start = local_offset + 30 + local_name_len + local_extra_len
    let data = bytes_to_string(bytes_slice(buf, data_start, data_start + uncomp_size))
    let entries = append(entries, [name, data])
    let off = off + 46 + name_len + extra_len + comment_len
  }
  auto entries
}
"""
}

lib/ttf.sl.content:
shape lib.ttf : lib {
  type: lib
  layer: 3
  """
// TTF metadata parsing — pure shape-lang on byte primitives.

fn ttf_info(buf) {
  // Parse TTF/TrueType font file, return [[key, value], ...]
  if len(buf) < 12 { auto [] }
  let scaler = read_u32_be(buf, 0)
  if scaler != 0x00010000 {
    if scaler != 0x74727565 { auto [] }
  }
  let num_tables = read_u16_be(buf, 4)
  if len(buf) < 12 + num_tables * 16 { auto [] }
  // Build table directory: find offsets for head, hhea, OS/2, name.
  let result = [["weight", "400"], ["style", "regular"]]
  let head_off = 0
  let hhea_off = 0
  let os2_off = 0
  let name_off = 0
  let name_len = 0
  let i = 0
  while i < num_tables {
    let off = 12 + i * 16
    let tag = bytes_to_string(bytes_slice(buf, off, off + 4))
    let toff = read_u32_be(buf, off + 8)
    let tlen = read_u32_be(buf, off + 12)
    if tag == "head" { let head_off = toff }
    if tag == "hhea" { let hhea_off = toff }
    if tag == "OS/2" { let os2_off = toff }
    if tag == "name" { let name_off = toff; let name_len = tlen }
    let i = i + 1
  }
  // head: unitsPerEm at offset+18
  if head_off > 0 {
    if head_off + 54 <= len(buf) {
      let upm = read_u16_be(buf, head_off + 18)
      let result = append(result, ["units_per_em", to_string(upm)])
    }
  }
  // hhea: ascent(+4), descent(+6), lineGap(+8)
  if hhea_off > 0 {
    if hhea_off + 36 <= len(buf) {
      let result = append(result, ["ascent", to_string(read_i16_be(buf, hhea_off + 4))])
      let result = append(result, ["descent", to_string(read_i16_be(buf, hhea_off + 6))])
      let result = append(result, ["line_gap", to_string(read_i16_be(buf, hhea_off + 8))])
    }
  }
  // OS/2: weight at offset+4
  if os2_off > 0 {
    if os2_off + 8 <= len(buf) {
      let w = read_u16_be(buf, os2_off + 4)
      // Update result[0]
      let result = append(result, ["weight_class", to_string(w)])
    }
  }
  // name: family(nameID=1), style(nameID=2)
  if name_off > 0 {
    if name_off + 6 <= len(buf) {
      let count = read_u16_be(buf, name_off + 2)
      let str_offset = read_u16_be(buf, name_off + 4)
      let j = 0
      while j < count {
        let rec = name_off + 6 + j * 12
        let j = j + 1
        if rec + 12 > len(buf) { break }
        let platform = read_u16_be(buf, rec)
        let name_id = read_u16_be(buf, rec + 6)
        let slen = read_u16_be(buf, rec + 8)
        let soff = read_u16_be(buf, rec + 10)
        let abs_off = name_off + str_offset + soff
        if abs_off + slen > len(buf) { continue }
        // Platform 1 = Macintosh (ASCII), platform 3 = Windows (UTF-16BE).
        if platform == 1 {
          let s = bytes_to_string(bytes_slice(buf, abs_off, abs_off + slen))
          if name_id == 1 { let result = append(result, ["family", s]) }
          if name_id == 2 { let result = append(result, ["style_name", s]) }
        }
        if platform == 3 {
          // Decode UTF-16BE: pairs of bytes → characters.
          let s = ""
          let k = 0
          while k < slen {
            let cp = read_u16_be(buf, abs_off + k)
            let s = s + chr(cp)
            let k = k + 2
          }
          if name_id == 1 { let result = append(result, ["family", s]) }
          if name_id == 2 { let result = append(result, ["style_name", s]) }
        }
      }
    }
  }
  auto result
}
"""
}

lib/json.sl.content:
shape lib.json : lib {
  type: lib
  layer: 3
  """
// JSON string escaping — pure shape-lang.

fn json_escape(s) {
  let out = ""
  let i = 0
  let n = len(s)
  while i < n {
    let c = at(s, i)
    let i = i + 1
    let code = ord(c)
    if c == "\\" { let out = out + "\\\\" }
    if c != "\\" {
      if c == "\"" { let out = out + "\\\"" }
      if c != "\"" {
        if code == 10 { let out = out + "\\n" }
        if code == 13 { let out = out + "\\r" }
        if code == 9 { let out = out + "\\t" }
        if code != 10 {
          if code != 13 {
            if code != 9 {
              let out = out + c
            }
          }
        }
      }
    }
  }
  auto out
}
"""
}

