os/wm/tiling/style.sl.content:
shape os.wm.tiling.style : os.wm.tiling {
  type: style
  layer: 4
  """
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  overflow: hidden;
}
#statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 28px;
  padding: 0 12px;
  background: var(--statusbar);
  color: var(--statusbar-text);
  font-size: 11px;
  border-bottom: 1px solid var(--border);
  -webkit-app-region: drag;
}
#statusbar-left { display: flex; gap: 4px; }
#statusbar-center {
  font-family: 'SF Mono', monospace;
  color: var(--fg-dim);
  font-weight: 600;
}
#statusbar-right { display: flex; gap: 12px; }
.ws-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  -webkit-app-region: no-drag;
}
.ws-indicator:hover { background: var(--bg-lighter); color: var(--fg); }
.ws-indicator.active { background: var(--accent); color: var(--bg); }
#workspace {
  height: calc(100% - 28px);
  position: relative;
}
.workspace {
  position: absolute;
  inset: 0;
  display: none;
}
.workspace.active { display: flex; }
.split {
  display: flex;
  flex: 1;
  gap: 2px;
}
.hsplit { flex-direction: row; }
.vsplit { flex-direction: column; }
.window {
  flex: 1;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  margin: 2px;
}
.window.focused { border-color: var(--border-focus); }
.window-titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 28px;
  padding: 0 10px;
  background: var(--titlebar);
  color: var(--titlebar-text);
  font-size: 11px;
  font-weight: 600;
  cursor: default;
  flex-shrink: 0;
}
.window.focused .window-titlebar { color: var(--fg); }
.window-title { flex: 1; }
.window-controls { display: flex; gap: 6px; }
.win-btn {
  background: none;
  border: none;
  color: var(--fg-dim);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  padding: 0 2px;
}
.win-btn:hover { color: var(--fg); }
.win-btn.close:hover { color: var(--red); }
.window-content { flex: 1; overflow: hidden; }
.window-content iframe { width: 100%; height: 100%; border: none; }
#launcher {
  position: fixed;
  inset: 0;
  z-index: 100;
}
.launcher-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.5);
}
.launcher-content {
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  width: 400px;
  background: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}
#launcher-input {
  width: 100%;
  padding: 12px 16px;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
  font-size: 14px;
  outline: none;
}
.launcher-results { padding: 4px 0; }
.launcher-item {
  padding: 8px 16px;
  cursor: pointer;
  font-size: 13px;
}
.launcher-item:hover,
.launcher-item.selected { background: var(--accent); color: var(--bg); }
/* Resize gutter between tiled windows */
.resize-gutter {
  flex: 0 0 6px;
  background: var(--border);
  cursor: col-resize;
  z-index: 10;
  transition: background 0.15s;
}
.resize-gutter:hover,
.resize-gutter.dragging { background: var(--accent); }
.vsplit > .resize-gutter { cursor: row-resize; }
/* During drag, prevent iframes from stealing mouse events */
.resizing iframe { pointer-events: none; }
/* Windows use explicit flex-basis when resized, not flex:1 */
.window.sized { flex: 0 0 auto; }
"""
}

os/wm/tiling/script.sl.content:
shape os.wm.tiling.script : os.wm.tiling {
  type: script
  layer: 4
  """
(function() {
  var currentWs = document.querySelector('.workspace.active');

  function switchWorkspace(n) {
    document.querySelectorAll('.workspace').forEach(function(ws) {
      ws.classList.toggle('active', ws.dataset.ws === String(n));
    });
    document.querySelectorAll('.ws-indicator').forEach(function(ind) {
      ind.classList.toggle('active', ind.dataset.ws === String(n));
    });
    currentWs = document.querySelector('.workspace.active');
    fetch('/desktop/workspace', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({workspace: String(n)})
    });
  }

  document.querySelectorAll('.ws-indicator').forEach(function(ind) {
    ind.addEventListener('click', function() {
      switchWorkspace(parseInt(this.dataset.ws));
    });
  });

  function bindWindowEvents(win) {
    win.addEventListener('mousedown', function() {
      document.querySelectorAll('.window').forEach(function(w) { w.classList.remove('focused'); });
      this.classList.add('focused');
      var id = this.dataset.id;
      if (id) {
        fetch('/desktop/focus', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({id: id})
        });
      }
    });
    var closeBtn = win.querySelector('.win-btn.close');
    if (closeBtn) {
      closeBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        var id = win.dataset.id;
        if (id) fetch('/desktop/window/' + id, {method: 'DELETE'});
        win.remove();
      });
    }
  }
  document.querySelectorAll('.window').forEach(bindWindowEvents);

  var launcher = document.getElementById('launcher');
  var launcherInput = document.getElementById('launcher-input');

  function openLauncher() {
    launcher.style.display = '';
    launcherInput.value = '';
    launcherInput.focus();
    filterLauncher('');
  }
  function closeLauncher() { launcher.style.display = 'none'; }
  function filterLauncher(query) {
    query = query.toLowerCase();
    document.querySelectorAll('.launcher-item').forEach(function(item) {
      item.style.display = item.textContent.toLowerCase().indexOf(query) >= 0 ? '' : 'none';
    });
  }

  if (launcherInput) {
    launcherInput.addEventListener('input', function() { filterLauncher(this.value); });
    launcherInput.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeLauncher();
      if (e.key === 'Enter') {
        var visible = document.querySelector('.launcher-item:not([style*="display: none"])');
        if (visible) launchApp(visible.dataset.app);
        closeLauncher();
      }
    });
  }
  if (document.querySelector('.launcher-backdrop')) {
    document.querySelector('.launcher-backdrop').addEventListener('click', closeLauncher);
  }
  document.querySelectorAll('.launcher-item').forEach(function(item) {
    item.addEventListener('click', function() {
      launchApp(this.dataset.app);
      closeLauncher();
    });
  });

  function launchApp(name) {
    var wsNum = currentWs ? currentWs.dataset.ws : '1';
    Promise.all([
      fetch('/desktop/window', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({workspace: wsNum, app: name})
      }).then(function(r) { return r.json(); }),
      fetch('/desktop/appurl/' + name).then(function(r) { return r.json(); })
    ]).then(function(results) {
      var data = results[0];
      var url = results[1].url;
      var ws = currentWs;
      var split = ws.querySelector('.split');
      if (!split) {
        split = document.createElement('div');
        split.className = 'split hsplit';
        ws.appendChild(split);
      }
      var win = document.createElement('div');
      win.className = 'window focused';
      win.dataset.app = name;
      win.dataset.id = data.id;
      win.innerHTML = '<div class="window-titlebar"><span class="window-title">' + name +
        '</span><span class="window-controls"><button class="win-btn close">&times;</button></span></div>' +
        '<div class="window-content"><iframe src="' + url + '" frameborder="0"></iframe></div>';
      split.appendChild(win);
      bindWindowEvents(win);
      document.querySelectorAll('.window').forEach(function(w) { w.classList.remove('focused'); });
      win.classList.add('focused');
    });
  }

  document.addEventListener('keydown', function(e) {
    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
      switchWorkspace(parseInt(e.key));
      e.preventDefault();
    }
    if ((e.metaKey || e.ctrlKey) && e.key === ' ') {
      if (launcher.style.display === 'none') openLauncher();
      else closeLauncher();
      e.preventDefault();
    }
    if (e.ctrlKey && e.key === 'Enter') {
      launchApp('shell');
      e.preventDefault();
    }
    if (e.ctrlKey && e.key === 'w') {
      var fw = document.querySelector('.window.focused');
      if (fw) {
        var id = fw.dataset.id;
        if (id) fetch('/desktop/window/' + id, {method: 'DELETE'});
        fw.remove();
      }
      e.preventDefault();
    }
  });

  // --- Resize gutters between tiled windows ---
  function insertGutters() {
    document.querySelectorAll('.split').forEach(function(split) {
      var windows = Array.from(split.children).filter(function(c) {
        return c.classList.contains('window');
      });
      // Remove old gutters.
      split.querySelectorAll('.resize-gutter').forEach(function(g) { g.remove(); });
      // Insert gutter between each pair.
      for (var i = 0; i < windows.length - 1; i++) {
        var gutter = document.createElement('div');
        gutter.className = 'resize-gutter';
        windows[i].after(gutter);
      }
    });
  }
  insertGutters();

  // Drag logic.
  var dragGutter = null, dragSplit = null, dragPrev = null, dragNext = null, dragStart = 0, dragTotal = 0;

  document.addEventListener('mousedown', function(e) {
    if (!e.target.classList.contains('resize-gutter')) return;
    dragGutter = e.target;
    dragSplit = dragGutter.parentElement;
    var isH = dragSplit.classList.contains('hsplit');
    // Find adjacent windows.
    var prev = dragGutter.previousElementSibling;
    var next = dragGutter.nextElementSibling;
    if (!prev || !next) return;
    dragPrev = prev;
    dragNext = next;
    dragGutter.classList.add('dragging');
    document.body.classList.add('resizing');
    var prevRect = prev.getBoundingClientRect();
    var nextRect = next.getBoundingClientRect();
    dragTotal = isH ? (prevRect.width + nextRect.width) : (prevRect.height + nextRect.height);
    dragStart = isH ? e.clientX : e.clientY;
    // Set initial sizes.
    var prevSize = isH ? prevRect.width : prevRect.height;
    prev.style.flex = '0 0 ' + prevSize + 'px';
    prev.classList.add('sized');
    next.style.flex = '1 1 0';
    e.preventDefault();
  });

  document.addEventListener('mousemove', function(e) {
    if (!dragGutter) return;
    var isH = dragSplit.classList.contains('hsplit');
    var delta = (isH ? e.clientX : e.clientY) - dragStart;
    var prevRect = dragPrev.getBoundingClientRect();
    var currentSize = isH ? prevRect.width : prevRect.height;
    var newSize = currentSize + delta;
    // Clamp: min 80px, max total - 80px.
    if (newSize < 80) newSize = 80;
    if (newSize > dragTotal - 80) newSize = dragTotal - 80;
    dragPrev.style.flex = '0 0 ' + newSize + 'px';
    dragStart = isH ? e.clientX : e.clientY;
    e.preventDefault();
  });

  document.addEventListener('mouseup', function() {
    if (!dragGutter) return;
    dragGutter.classList.remove('dragging');
    document.body.classList.remove('resizing');
    dragGutter = null;
  });
})();
"""
}

os/wm/floating/style.sl.content:
shape os.wm.floating.style : os.wm.floating {
  type: style
  layer: 4
  """
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  overflow: hidden;
}
/* Workspace is the desktop surface */
#workspace {
  position: absolute;
  top: 0; left: 0; right: 0;
  bottom: 36px; /* room for taskbar */
  overflow: hidden;
}
.workspace {
  position: absolute;
  inset: 0;
  display: none;
}
.workspace.active { display: block; }
.workspace::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--desktop-bg, linear-gradient(135deg, var(--bg-dark) 0%, var(--bg) 50%, var(--bg-lighter) 100%));
  z-index: -1;
}
/* Free-floating windows */
.window {
  position: absolute;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
  background: var(--bg);
  box-shadow: 0 4px 20px rgba(0,0,0,0.4);
  min-width: 200px;
  min-height: 120px;
}
.window.focused {
  border-color: var(--border-focus);
  box-shadow: 0 8px 30px rgba(0,0,0,0.5);
  z-index: 50;
}
.window.maximized {
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: 0;
}
.window.minimized { display: none; }
.window-titlebar {
  display: flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  background: var(--titlebar);
  color: var(--titlebar-text);
  font-size: 12px;
  font-weight: 600;
  cursor: default;
  flex-shrink: 0;
  user-select: none;
  -webkit-user-select: none;
}
.window.focused .window-titlebar { color: var(--fg); }
.window-title { flex: 1; cursor: grab; }
.window-title:active { cursor: grabbing; }
.window-controls { display: flex; gap: 2px; }
.win-btn {
  background: none;
  border: none;
  color: var(--fg-dim);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  width: 28px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
}
.win-btn:hover { background: var(--bg-lighter); color: var(--fg); }
.win-btn.close:hover { background: var(--red); color: var(--bg); }
.window-content { flex: 1; overflow: hidden; }
.window-content iframe { width: 100%; height: 100%; border: none; }
/* Resize handles */
.window .resize-handle {
  position: absolute;
  z-index: 10;
}
.resize-handle.n  { top: -3px; left: 6px; right: 6px; height: 6px; cursor: n-resize; }
.resize-handle.s  { bottom: -3px; left: 6px; right: 6px; height: 6px; cursor: s-resize; }
.resize-handle.e  { right: -3px; top: 6px; bottom: 6px; width: 6px; cursor: e-resize; }
.resize-handle.w  { left: -3px; top: 6px; bottom: 6px; width: 6px; cursor: w-resize; }
.resize-handle.ne { top: -3px; right: -3px; width: 10px; height: 10px; cursor: ne-resize; }
.resize-handle.nw { top: -3px; left: -3px; width: 10px; height: 10px; cursor: nw-resize; }
.resize-handle.se { bottom: -3px; right: -3px; width: 10px; height: 10px; cursor: se-resize; }
.resize-handle.sw { bottom: -3px; left: -3px; width: 10px; height: 10px; cursor: sw-resize; }
/* Prevent iframe stealing events during drag/resize */
body.dragging iframe,
body.resizing iframe { pointer-events: none; }
/* Taskbar */
#taskbar {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 36px;
  display: flex;
  align-items: center;
  background: var(--statusbar);
  border-top: 1px solid var(--border);
  padding: 0 8px;
  gap: 2px;
  z-index: 100;
}
#taskbar-start {
  padding: 4px 12px;
  font-size: 11px;
  font-weight: 700;
  color: var(--accent);
  cursor: pointer;
  border-radius: 3px;
  margin-right: 4px;
}
#taskbar-start:hover { background: var(--bg-lighter); }
.taskbar-item {
  padding: 4px 12px;
  font-size: 11px;
  color: var(--statusbar-text);
  cursor: pointer;
  border-radius: 3px;
  white-space: nowrap;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.taskbar-item:hover { background: var(--bg-lighter); color: var(--fg); }
.taskbar-item.active { background: var(--bg-lighter); color: var(--fg); border-bottom: 2px solid var(--accent); }
#taskbar-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  color: var(--statusbar-text);
  padding-right: 8px;
}
.ws-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}
.ws-indicator:hover { background: var(--bg-lighter); color: var(--fg); }
.ws-indicator.active { background: var(--accent); color: var(--bg); }
/* Statusbar hidden in floating mode — replaced by taskbar */
#statusbar { display: none; }
/* Launcher */
#launcher {
  position: fixed;
  inset: 0;
  z-index: 200;
}
.launcher-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.5);
}
.launcher-content {
  position: absolute;
  bottom: 44px;
  left: 8px;
  width: 320px;
  background: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}
#launcher-input {
  width: 100%;
  padding: 10px 14px;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
  font-size: 13px;
  outline: none;
}
.launcher-results { padding: 4px 0; max-height: 300px; overflow-y: auto; }
.launcher-item {
  padding: 8px 14px;
  cursor: pointer;
  font-size: 13px;
}
.launcher-item:hover,
.launcher-item.selected { background: var(--accent); color: var(--bg); }
/* Hide tiling constructs */
.split { display: contents; }
"""
}

os/wm/floating/script.sl.content:
shape os.wm.floating.script : os.wm.floating {
  type: script
  layer: 4
  """
(function() {
  var zIndex = 100;
  var currentWs = document.querySelector('.workspace.active');

  // --- Taskbar ---
  var taskbar = document.getElementById('taskbar');
  if (!taskbar) {
    taskbar = document.createElement('div');
    taskbar.id = 'taskbar';
    document.body.appendChild(taskbar);
  }
  taskbar.innerHTML = '<div id="taskbar-start">Shape</div><div id="taskbar-items"></div><div id="taskbar-right"></div>';
  var taskbarItems = taskbar.querySelector('#taskbar-items');
  if (!taskbarItems) {
    taskbarItems = document.createElement('div');
    taskbarItems.id = 'taskbar-items';
    taskbarItems.style.cssText = 'display:flex;gap:2px;flex:1;overflow:hidden;';
    taskbar.insertBefore(taskbarItems, taskbar.querySelector('#taskbar-right'));
  }

  // Workspace indicators in taskbar-right.
  var taskbarRight = taskbar.querySelector('#taskbar-right');
  var wsHtml = '';
  document.querySelectorAll('.ws-indicator').forEach(function(ind) {
    wsHtml += '<span class="ws-indicator' + (ind.classList.contains('active') ? ' active' : '') + '" data-ws="' + ind.dataset.ws + '">' + ind.dataset.ws + '</span>';
  });
  taskbarRight.innerHTML = wsHtml + '<span id="taskbar-clock"></span>';

  // Clock.
  function updateClock() {
    var el = document.getElementById('taskbar-clock');
    if (el) {
      var d = new Date();
      el.textContent = d.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    }
  }
  updateClock();
  setInterval(updateClock, 30000);

  // Workspace switching.
  function switchWorkspace(n) {
    document.querySelectorAll('.workspace').forEach(function(ws) {
      ws.classList.toggle('active', ws.dataset.ws === String(n));
    });
    taskbarRight.querySelectorAll('.ws-indicator').forEach(function(ind) {
      ind.classList.toggle('active', ind.dataset.ws === String(n));
    });
    currentWs = document.querySelector('.workspace.active');
    updateTaskbar();
    fetch('/desktop/workspace', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({workspace: String(n)})
    });
  }
  taskbarRight.addEventListener('click', function(e) {
    var ind = e.target.closest('.ws-indicator');
    if (ind) switchWorkspace(parseInt(ind.dataset.ws));
  });

  // --- Position windows ---
  function positionWindows() {
    document.querySelectorAll('.workspace').forEach(function(ws) {
      var wins = ws.querySelectorAll('.window');
      var total = wins.length;
      wins.forEach(function(win, i) {
        if (!win.style.left || win.style.left === '0px') {
          var offset = 30 + i * 30;
          var w = Math.min(800, window.innerWidth * 0.6);
          var h = Math.min(600, (window.innerHeight - 36) * 0.7);
          win.style.left = offset + 'px';
          win.style.top = offset + 'px';
          win.style.width = w + 'px';
          win.style.height = h + 'px';
        }
        addResizeHandles(win);
      });
    });
  }

  function addResizeHandles(win) {
    if (win.querySelector('.resize-handle')) return;
    ['n','s','e','w','ne','nw','se','sw'].forEach(function(dir) {
      var h = document.createElement('div');
      h.className = 'resize-handle ' + dir;
      h.dataset.dir = dir;
      win.appendChild(h);
    });
  }

  positionWindows();

  // --- Focus ---
  function focusWindow(win) {
    document.querySelectorAll('.window').forEach(function(w) { w.classList.remove('focused'); });
    win.classList.add('focused');
    win.style.zIndex = ++zIndex;
    updateTaskbar();
    var id = win.dataset.id;
    if (id) {
      fetch('/desktop/focus', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({id: id})
      });
    }
  }

  // --- Drag ---
  var dragWin = null, dragX = 0, dragY = 0;

  function onTitleMousedown(e) {
    var win = e.target.closest('.window');
    if (!win || e.target.closest('.win-btn')) return;
    if (win.classList.contains('maximized')) return;
    dragWin = win;
    dragX = e.clientX - win.offsetLeft;
    dragY = e.clientY - win.offsetTop;
    document.body.classList.add('dragging');
    focusWindow(win);
    e.preventDefault();
  }

  document.addEventListener('mousemove', function(e) {
    if (dragWin) {
      dragWin.style.left = (e.clientX - dragX) + 'px';
      dragWin.style.top = (e.clientY - dragY) + 'px';
      e.preventDefault();
    }
    if (resizeWin) {
      doResize(e);
      e.preventDefault();
    }
  });

  document.addEventListener('mouseup', function() {
    if (dragWin) {
      // Apply snap if dragged to an edge zone.
      if (snapZone) {
        var r = snapRect(snapZone);
        if (r) {
          dragWin.classList.remove('maximized');
          dragWin.style.left = r.left + 'px';
          dragWin.style.top = r.top + 'px';
          dragWin.style.width = r.width + 'px';
          dragWin.style.height = r.height + 'px';
        }
        snapZone = null;
        if (typeof snapPreview !== 'undefined') snapPreview.style.display = 'none';
      }
      saveWindowGeometryDebounced(dragWin);
      document.body.classList.remove('dragging');
      dragWin = null;
    }
    if (resizeWin) {
      saveWindowGeometryDebounced(resizeWin);
      document.body.classList.remove('resizing');
      resizeWin = null;
    }
  });

  // --- Resize ---
  var resizeWin = null, resizeDir = '', resizeStartX = 0, resizeStartY = 0;
  var resizeStartW = 0, resizeStartH = 0, resizeStartL = 0, resizeStartT = 0;

  document.addEventListener('mousedown', function(e) {
    var handle = e.target.closest('.resize-handle');
    if (!handle) return;
    var win = handle.closest('.window');
    if (!win || win.classList.contains('maximized')) return;
    resizeWin = win;
    resizeDir = handle.dataset.dir;
    resizeStartX = e.clientX;
    resizeStartY = e.clientY;
    resizeStartW = win.offsetWidth;
    resizeStartH = win.offsetHeight;
    resizeStartL = win.offsetLeft;
    resizeStartT = win.offsetTop;
    document.body.classList.add('resizing');
    focusWindow(win);
    e.preventDefault();
  });

  function doResize(e) {
    var dx = e.clientX - resizeStartX;
    var dy = e.clientY - resizeStartY;
    var d = resizeDir;
    var w = resizeStartW, h = resizeStartH, l = resizeStartL, t = resizeStartT;
    if (d.indexOf('e') >= 0) w = Math.max(200, resizeStartW + dx);
    if (d.indexOf('w') >= 0) { w = Math.max(200, resizeStartW - dx); l = resizeStartL + (resizeStartW - w); }
    if (d.indexOf('s') >= 0) h = Math.max(120, resizeStartH + dy);
    if (d.indexOf('n') >= 0) { h = Math.max(120, resizeStartH - dy); t = resizeStartT + (resizeStartH - h); }
    resizeWin.style.width = w + 'px';
    resizeWin.style.height = h + 'px';
    resizeWin.style.left = l + 'px';
    resizeWin.style.top = t + 'px';
  }

  // --- Window buttons ---
  function bindWindowEvents(win) {
    win.addEventListener('mousedown', function(e) {
      if (!e.target.closest('.resize-handle')) focusWindow(win);
    });
    var titlebar = win.querySelector('.window-title');
    if (titlebar) titlebar.addEventListener('mousedown', onTitleMousedown);
    win.querySelectorAll('.win-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        if (btn.classList.contains('close')) {
          var id = win.dataset.id;
          if (id) fetch('/desktop/window/' + id, {method: 'DELETE'});
          win.remove();
          updateTaskbar();
        } else if (btn.classList.contains('maximize')) {
          win.classList.toggle('maximized');
        } else if (btn.classList.contains('minimize')) {
          win.classList.add('minimized');
          updateTaskbar();
        }
      });
    });
  }

  // Add maximize and minimize buttons to existing windows.
  document.querySelectorAll('.window').forEach(function(win) {
    var controls = win.querySelector('.window-controls');
    if (controls && !controls.querySelector('.minimize')) {
      var minBtn = document.createElement('button');
      minBtn.className = 'win-btn minimize';
      minBtn.title = 'minimize';
      minBtn.innerHTML = '&#8211;';
      var maxBtn = document.createElement('button');
      maxBtn.className = 'win-btn maximize';
      maxBtn.title = 'maximize';
      maxBtn.innerHTML = '&#9633;';
      var closeBtn = controls.querySelector('.close');
      controls.insertBefore(minBtn, closeBtn);
      controls.insertBefore(maxBtn, closeBtn);
    }
    bindWindowEvents(win);
  });

  // --- Taskbar ---
  function updateTaskbar() {
    if (!taskbarItems) return;
