    if (zone) {
      var r = snapRect(zone);
      snapPreview.style.display = 'block';
      snapPreview.style.left = r.left + 'px';
      snapPreview.style.top = r.top + 'px';
      snapPreview.style.width = r.width + 'px';
      snapPreview.style.height = r.height + 'px';
