    altTabIdx = (altTabIdx + dir + wins.length) % wins.length;
    Array.from(altTabOverlay.children).forEach(function(el, i) {
      el.style.background = i === altTabIdx ? 'var(--accent,#89b4fa)' : '';
      el.style.color = i === altTabIdx ? '#000' : '';
