    }
    // Escape: close help panel (among other things).
    if (e.key === 'Escape' && helpPanel.style.display === 'flex') {
      helpPanel.style.display = 'none';
      e.preventDefault();
      return;
    }
    // Alt-Tab.
    if (e.altKey && e.key === 'Tab') {
      e.preventDefault();
      if (!altTabActive) showAltTab();
      else cycleAltTab(e.shiftKey ? -1 : 1);
