os/render/sheet/script.sl.content:
shape os.render.sheet.script {
  type: script
  layer: 4
  """
(function() {
  var root = document.getElementById('sheet');
  var sheetId = root.dataset.id;
  var cols = 26, rows = 50;
  var cells = {};
  var selectedCell = null;
  var editingCell = null;

  // Build toolbar.
  var toolbar = document.createElement('div');
  toolbar.className = 'sheet-toolbar';
  toolbar.innerHTML = '<button onclick="newSheet()">New</button>' +
    '<button id="btn-bold" onclick="toggleBold()">B</button>' +
    '<button id="btn-export" onclick="exportCSV()">Export CSV</button>' +
    '<span style="flex:1"></span>' +
    '<span id="sheet-title">' + (sheetId || 'Untitled') + '</span>';
  root.appendChild(toolbar);

  // Formula bar.
  var formulaBar = document.createElement('div');
  formulaBar.className = 'formula-bar';
  formulaBar.innerHTML = '<span class="cell-ref" id="cell-ref">A1</span>' +
    '<input id="formula-input" placeholder="Enter value or formula (=SUM(A1:A5))">';
  root.appendChild(formulaBar);
  var formulaInput = document.getElementById('formula-input');
  var cellRefDisplay = document.getElementById('cell-ref');

  // Grid container.
  var gridContainer = document.createElement('div');
  gridContainer.className = 'grid-container';
  root.appendChild(gridContainer);

  var grid = document.createElement('div');
  grid.className = 'grid';
  grid.style.gridTemplateColumns = '40px ' + Array(cols).fill('80px').join(' ');
  gridContainer.appendChild(grid);

  // Status bar.
  var statusBar = document.createElement('div');
  statusBar.className = 'sheet-status';
  statusBar.innerHTML = '<span id="status-left">Ready</span><span id="status-right"></span>';
  root.appendChild(statusBar);

  function colLetter(i) { return String.fromCharCode(65 + i); }
  function cellId(c, r) { return colLetter(c) + (r + 1); }

  // Build grid.
  function buildGrid() {
    grid.innerHTML = '';
    // Corner.
    var corner = document.createElement('div');
    corner.className = 'corner';
    grid.appendChild(corner);

    // Column headers.
    for (var c = 0; c < cols; c++) {
      var ch = document.createElement('div');
      ch.className = 'col-header';
      ch.textContent = colLetter(c);
      ch.dataset.col = c;
      grid.appendChild(ch);
    }

    // Rows.
    for (var r = 0; r < rows; r++) {
      // Row header.
      var rh = document.createElement('div');
      rh.className = 'row-header';
      rh.textContent = r + 1;
      grid.appendChild(rh);

      for (var c = 0; c < cols; c++) {
        var cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.col = c;
        cell.dataset.row = r;
        cell.dataset.id = cellId(c, r);
        cell.tabIndex = 0;

        // Load existing value.
        var id = cellId(c, r);
        if (cells[id]) {
          cell.textContent = cells[id].value || '';
        }

        cell.addEventListener('click', onCellClick);
        cell.addEventListener('dblclick', onCellDblClick);
        cell.addEventListener('keydown', onCellKeydown);
        grid.appendChild(cell);
      }
    }
  }

  function onCellClick(e) {
    if (editingCell) commitEdit();
    selectCell(e.target);
  }

  function selectCell(el) {
    if (selectedCell) selectedCell.classList.remove('selected');
    selectedCell = el;
    el.classList.add('selected');
    el.focus();
    var id = el.dataset.id;
    cellRefDisplay.textContent = id;
    var data = cells[id];
    formulaInput.value = data ? (data.formula || data.value || '') : '';
  }

  function onCellDblClick(e) {
    startEdit(e.target);
  }

  function startEdit(el) {
    editingCell = el;
    el.classList.add('editing');
    el.contentEditable = true;
    el.focus();
    // Show formula if present.
    var id = el.dataset.id;
    if (cells[id] && cells[id].formula) {
      el.textContent = cells[id].formula;
    }
  }

  function commitEdit() {
    if (!editingCell) return;
    var el = editingCell;
    el.contentEditable = false;
    el.classList.remove('editing');
    var id = el.dataset.id;
    var val = el.textContent.trim();

    var cellData = { value: val, format: 'general' };
    if (val.startsWith('=')) {
      cellData.formula = val;
      cellData.format = 'formula';
      cellData.value = evalFormula(val, id);
      el.textContent = cellData.value;
    }
    cells[id] = cellData;
    editingCell = null;

    // POST to server.
    if (sheetId) {
      fetch('/office/sheet/' + sheetId + '/cell', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          cell: id,
          value: cellData.value,
          format: cellData.format,
          formula: cellData.formula || ''
        })
      });
    }

    updateStatus();
  }

  function evalFormula(formula, cellId) {
    // Simple formula evaluation.
    var expr = formula.substring(1).trim();

    // SUM(A1:A5) pattern.
    var sumMatch = expr.match(/^SUM\(([A-Z])(\d+):([A-Z])(\d+)\)$/i);
    if (sumMatch) {
      var c1 = sumMatch[1].toUpperCase().charCodeAt(0) - 65;
      var r1 = parseInt(sumMatch[2]) - 1;
      var c2 = sumMatch[3].toUpperCase().charCodeAt(0) - 65;
      var r2 = parseInt(sumMatch[4]) - 1;
      var total = 0;
      for (var r = r1; r <= r2; r++) {
        for (var c = c1; c <= c2; c++) {
          var ref = colLetter(c) + (r + 1);
          if (cells[ref]) total += parseFloat(cells[ref].value) || 0;
        }
      }
      return String(total);
    }

    // AVERAGE pattern.
    var avgMatch = expr.match(/^AVERAGE\(([A-Z])(\d+):([A-Z])(\d+)\)$/i);
    if (avgMatch) {
      var c1 = avgMatch[1].toUpperCase().charCodeAt(0) - 65;
      var r1 = parseInt(avgMatch[2]) - 1;
      var c2 = avgMatch[3].toUpperCase().charCodeAt(0) - 65;
      var r2 = parseInt(avgMatch[4]) - 1;
      var total = 0, count = 0;
      for (var r = r1; r <= r2; r++) {
        for (var c = c1; c <= c2; c++) {
          var ref = colLetter(c) + (r + 1);
          if (cells[ref]) { total += parseFloat(cells[ref].value) || 0; count++; }
        }
      }
      return count > 0 ? String(total / count) : '0';
    }

    // Simple cell references: =A1+B1.
    var resolved = expr.replace(/([A-Z])(\d+)/gi, function(m, col, row) {
      var ref = col.toUpperCase() + row;
      return cells[ref] ? (parseFloat(cells[ref].value) || 0) : 0;
    });
    try { return String(eval(resolved)); } catch(e) { return '#ERR'; }
  }

  function onCellKeydown(e) {
    var el = e.target;
    if (editingCell) {
      if (e.key === 'Enter') { e.preventDefault(); commitEdit(); moveDown(); }
      if (e.key === 'Tab') { e.preventDefault(); commitEdit(); moveRight(); }
      if (e.key === 'Escape') { cancelEdit(); }
      return;
    }

    // Navigation.
    var c = parseInt(el.dataset.col), r = parseInt(el.dataset.row);
    if (e.key === 'ArrowRight' || e.key === 'Tab') { e.preventDefault(); moveTo(c+1, r); }
    else if (e.key === 'ArrowLeft') { moveTo(c-1, r); }
    else if (e.key === 'ArrowDown' || e.key === 'Enter') { e.preventDefault(); moveTo(c, r+1); }
    else if (e.key === 'ArrowUp') { moveTo(c, r-1); }
    else if (e.key === 'Delete' || e.key === 'Backspace') {
      var id = el.dataset.id;
      delete cells[id];
      el.textContent = '';
    }
    else if (e.key.length === 1 && !e.ctrlKey && !e.metaKey) {
      // Start typing into cell.
      startEdit(el);
    }
  }

  function moveTo(c, r) {
    if (c < 0 || c >= cols || r < 0 || r >= rows) return;
    var id = cellId(c, r);
    var el = grid.querySelector('[data-id="' + id + '"]');
    if (el) selectCell(el);
  }
  function moveDown() { if (selectedCell) moveTo(parseInt(selectedCell.dataset.col), parseInt(selectedCell.dataset.row)+1); }
  function moveRight() { if (selectedCell) moveTo(parseInt(selectedCell.dataset.col)+1, parseInt(selectedCell.dataset.row)); }

  function cancelEdit() {
    if (!editingCell) return;
    var el = editingCell;
    el.contentEditable = false;
    el.classList.remove('editing');
    var id = el.dataset.id;
    el.textContent = cells[id] ? cells[id].value : '';
    editingCell = null;
  }

  function updateStatus() {
    var count = Object.keys(cells).length;
    document.getElementById('status-left').textContent = count + ' cells';
    // Sum of selected region (simplified: show selected cell value).
    if (selectedCell && cells[selectedCell.dataset.id]) {
      var v = parseFloat(cells[selectedCell.dataset.id].value);
      if (!isNaN(v)) {
        document.getElementById('status-right').textContent = 'Value: ' + v;
      }
    }
  }

  // Formula bar commit.
  formulaInput.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && selectedCell) {
      var val = formulaInput.value;
      var id = selectedCell.dataset.id;
      if (val.startsWith('=')) {
        cells[id] = { formula: val, value: evalFormula(val, id), format: 'formula' };
      } else {
        cells[id] = { value: val, format: 'general' };
      }
      selectedCell.textContent = cells[id].value;
      if (sheetId) {
        fetch('/office/sheet/' + sheetId + '/cell', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ cell: id, value: cells[id].value, format: cells[id].format, formula: cells[id].formula || '' })
        });
      }
    }
  });

  // Copy/paste support.
  document.addEventListener('copy', function(e) {
    if (selectedCell) {
      var id = selectedCell.dataset.id;
      e.clipboardData.setData('text/plain', cells[id] ? cells[id].value : '');
      e.preventDefault();
    }
  });

  // Load data from server.
  function loadData() {
    if (!sheetId) { buildGrid(); return; }
    fetch('/office/sheet/' + sheetId + '/data')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.cells) cells = data.cells;
        if (data.rows) rows = Math.max(rows, data.rows);
        if (data.cols) cols = Math.max(cols, data.cols);
        buildGrid();
      })
      .catch(function() { buildGrid(); });
  }

  // Export CSV.
  window.exportCSV = function() {
    var lines = [];
    for (var r = 0; r < rows; r++) {
      var row = [];
      for (var c = 0; c < cols; c++) {
        var id = cellId(c, r);
        row.push(cells[id] ? cells[id].value : '');
      }
      lines.push(row.join(','));
    }
    var blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = (sheetId || 'sheet') + '.csv';
    a.click();
  };

  window.newSheet = function() {
    var name = prompt('Sheet name:');
    if (name) window.location = '/office/sheet/user.sheet.' + name;
  };

  loadData();
})();
"""
}

os/render/editor/style.sl.content:
shape os.render.editor.style {
  type: style
  layer: 4
  """
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: var(--bg);
  color: var(--fg);
  font-family: 'SF Mono', 'Menlo', 'Consolas', monospace;
  font-size: 13px;
  height: 100vh;
  overflow: hidden;
}
#editor {
  display: flex;
  flex-direction: column;
  height: 100%;
}
#tabbar {
  display: flex;
  background: var(--bg-dark);
  border-bottom: 1px solid var(--border);
  height: 28px;
  align-items: center;
  overflow-x: auto;
  flex-shrink: 0;
}
.tab {
  padding: 4px 14px;
  font-size: 11px;
  color: var(--fg-dim);
  cursor: pointer;
  border-right: 1px solid var(--border);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 6px;
}
.tab:hover { color: var(--fg); }
.tab.active { background: var(--bg); color: var(--fg); }
.tab .modified { color: var(--yellow); }
.tab .tab-close {
  font-size: 14px;
  opacity: 0.4;
  cursor: pointer;
}
.tab .tab-close:hover { opacity: 1; color: var(--red); }
#viewport {
  flex: 1;
  display: flex;
  overflow: hidden;
  position: relative;
}
#gutter {
  width: 48px;
  background: var(--bg-dark);
  color: var(--fg-dim);
  text-align: right;
  padding: 4px 8px 4px 0;
  font-size: 12px;
  line-height: 20px;
  overflow: hidden;
  user-select: none;
  flex-shrink: 0;
  border-right: 1px solid var(--border);
}
#content {
  flex: 1;
  padding: 4px 8px;
  line-height: 20px;
  overflow-y: auto;
  overflow-x: hidden;
  white-space: pre;
  outline: none;
  position: relative;
}
.line {
  height: 20px;
  position: relative;
}
.line.current { background: var(--bg-lighter); }
.cursor-block {
  position: absolute;
  width: 7.8px;
  height: 18px;
  top: 1px;
  background: var(--cursor);
  opacity: 0.7;
  animation: blink 1s step-end infinite;
}
.cursor-line {
  position: absolute;
  width: 2px;
  height: 18px;
  top: 1px;
  background: var(--cursor);
  animation: blink 0.6s step-end infinite;
}
@keyframes blink { 50% { opacity: 0; } }
.search-match { background: var(--yellow); color: var(--bg); border-radius: 2px; }
.selection { background: var(--selection); }
#statusline {
  height: 24px;
  display: flex;
  align-items: center;
  padding: 0 8px;
  font-size: 11px;
  flex-shrink: 0;
}
#statusline.normal { background: var(--accent); color: var(--bg); }
#statusline.insert { background: var(--green); color: var(--bg); }
#statusline.visual { background: var(--yellow); color: var(--bg); }
#statusline.command { background: var(--bg-dark); color: var(--fg); }
#status-mode { font-weight: 700; margin-right: 12px; }
#status-file { flex: 1; }
#status-pos { margin-left: 12px; }
#commandline {
  height: 24px;
  display: flex;
  align-items: center;
  padding: 0 8px;
  background: var(--bg-dark);
  border-top: 1px solid var(--border);
  font-size: 12px;
  flex-shrink: 0;
}
#commandline input {
  background: transparent;
  border: none;
  color: var(--fg);
  font-family: inherit;
  font-size: 12px;
  flex: 1;
  outline: none;
}
#commandline .cmd-prefix {
  color: var(--accent);
  margin-right: 4px;
}
#commandline.hidden { display: none; }
#welcome {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fg-dim);
  font-size: 14px;
  text-align: center;
  line-height: 1.8;
}
"""
}

os/render/editor/script.sl.content:
shape os.render.editor.script {
  type: script
  layer: 4
  """
(function() {
  var root = document.getElementById('editor');

  // State.
  var buffers = [];       // [{id, lines, modified, cursor:{row,col}, scroll}]
  var activeIdx = -1;
  var mode = 'normal';    // normal, insert, command, search
  var cmdBuf = '';
  var searchTerm = '';
  var yankBuf = [];
  var message = '';
  var count = '';         // numeric prefix

  // DOM refs.
  var tabbar, viewport, gutter, content, statusline, commandline, cmdInput, welcome;

  function init() {
    root.innerHTML = '<div id="tabbar"></div>' +
      '<div id="viewport"><div id="gutter"></div><div id="content" tabindex="0"><div id="welcome">vip — vi perfected<br>shape editor<br><br>:e &lt;shape-id&gt; to open<br>:q to close</div></div></div>' +
      '<div id="statusline" class="normal"><span id="status-mode">NORMAL</span><span id="status-file"></span><span id="status-pos"></span></div>' +
      '<div id="commandline" class="hidden"><span class="cmd-prefix">:</span><input type="text" id="cmd-input"></div>';

    tabbar = document.getElementById('tabbar');
    viewport = document.getElementById('viewport');
    gutter = document.getElementById('gutter');
    content = document.getElementById('content');
    statusline = document.getElementById('statusline');
    commandline = document.getElementById('commandline');
    cmdInput = document.getElementById('cmd-input');
    welcome = document.getElementById('welcome');

    content.addEventListener('keydown', handleKey);
    content.addEventListener('click', handleClick);
    cmdInput.addEventListener('keydown', handleCmdKey);
    content.focus();

    // Open shape from URL param.
    var params = new URLSearchParams(window.location.search);
    var openId = params.get('id');
    if (openId) openBuffer(openId);
  }

  function buf() { return buffers[activeIdx]; }

  function openBuffer(id) {
    // Check if already open.
    for (var i = 0; i < buffers.length; i++) {
      if (buffers[i].id === id) { activeIdx = i; render(); return; }
    }
    // Fetch shape content.
    fetch('/shape/' + id).then(function(r) {
      if (!r.ok) { setMsg('shape not found: ' + id); render(); return r.text(); }
      return r.json();
    }).then(function(s) {
      if (!s || !s.id) return;
      var text = s.character ? (s.character.content || '') : '';
      var lines = text.split('\n');
      if (lines.length === 0) lines = [''];
      buffers.push({ id: s.id, lines: lines, modified: false, cursor: {row: 0, col: 0}, scroll: 0 });
      activeIdx = buffers.length - 1;
      render();
    });
  }

  function saveBuffer() {
    var b = buf();
    if (!b) return;
    var text = b.lines.join('\n');
    fetch('/shape', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({ id: b.id, character: { dimensions: {}, content: text } })
    }).then(function(r) {
      if (r.ok) { b.modified = false; setMsg('"' + b.id + '" written'); render(); }
      else { setMsg('save failed'); render(); }
    });
  }

  function closeBuffer(idx) {
    if (idx < 0 || idx >= buffers.length) return;
    buffers.splice(idx, 1);
    if (activeIdx >= buffers.length) activeIdx = buffers.length - 1;
    render();
  }

  function setMsg(m) { message = m; }

  // --- Rendering ---
  function render() {
    renderTabs();
    renderContent();
    renderStatus();
    if (welcome) welcome.style.display = buffers.length === 0 ? '' : 'none';
  }

  function renderTabs() {
    var html = '';
    for (var i = 0; i < buffers.length; i++) {
      var b = buffers[i];
      var cls = i === activeIdx ? ' active' : '';
      var mod = b.modified ? '<span class="modified">+</span>' : '';
      html += '<div class="tab' + cls + '" data-idx="' + i + '">' +
        b.id + mod + ' <span class="tab-close" data-close="' + i + '">&times;</span></div>';
    }
    tabbar.innerHTML = html;
    tabbar.querySelectorAll('.tab').forEach(function(t) {
      t.addEventListener('click', function(e) {
        if (e.target.classList.contains('tab-close')) {
          closeBuffer(parseInt(e.target.dataset.close));
          return;
        }
        activeIdx = parseInt(this.dataset.idx);
        render();
        content.focus();
      });
    });
  }

  function renderContent() {
    var b = buf();
    if (!b) { content.innerHTML = welcome ? welcome.outerHTML : ''; gutter.innerHTML = ''; return; }

    var viewH = viewport.offsetHeight;
    var lineH = 20;
    var visibleLines = Math.floor(viewH / lineH);
    // Ensure cursor is visible.
    if (b.cursor.row < b.scroll) b.scroll = b.cursor.row;
    if (b.cursor.row >= b.scroll + visibleLines) b.scroll = b.cursor.row - visibleLines + 1;

    var gutterHtml = '';
    var contentHtml = '';
    var end = Math.min(b.lines.length, b.scroll + visibleLines + 5);

    for (var i = b.scroll; i < end; i++) {
      var num = i + 1;
      gutterHtml += '<div style="height:20px">' + num + '</div>';

      var line = escHtml(b.lines[i]);
      var isCurrent = i === b.cursor.row;
      var cls = isCurrent ? ' current' : '';

      if (isCurrent) {
        var col = Math.min(b.cursor.col, b.lines[i].length);
        var before = escHtml(b.lines[i].substring(0, col));
        var cursorChar = b.lines[i][col] || ' ';
        var after = escHtml(b.lines[i].substring(col + 1));
        var cursorCls = mode === 'insert' ? 'cursor-line' : 'cursor-block';
        var charW = 7.8;
        var left = col * charW;
        line = before + '<span class="' + cursorCls + '" style="left:' + left + 'px"></span>' + escHtml(cursorChar) + after;
      }

      // Highlight search matches.
      if (searchTerm && !isCurrent) {
        var re = new RegExp(escRegex(searchTerm), 'gi');
        line = b.lines[i].replace(re, function(m) { return '<span class="search-match">' + escHtml(m) + '</span>'; });
      }

      contentHtml += '<div class="line' + cls + '">' + line + '</div>';
    }

    gutter.innerHTML = gutterHtml;
    gutter.style.paddingTop = '4px';
    content.innerHTML = contentHtml;
    content.scrollTop = 0;
  }

  function renderStatus() {
    var b = buf();
    var modeName = mode.toUpperCase();
    statusline.className = mode;
    document.getElementById('status-mode').textContent = '-- ' + modeName + ' --';
    document.getElementById('status-file').textContent = b ? (b.id + (b.modified ? ' [+]' : '')) : '';
    document.getElementById('status-pos').textContent = b ? ((b.cursor.row + 1) + ':' + (b.cursor.col + 1)) : '';

    if (message) {
      document.getElementById('status-file').textContent = message;
      message = '';
    }
  }

  // --- Input handling ---
  function handleKey(e) {
    if (mode === 'normal') normalKey(e);
    else if (mode === 'insert') insertKey(e);
    e.preventDefault();
    e.stopPropagation();
  }

  function handleClick(e) {
    content.focus();
    // TODO: click-to-position
  }

  function normalKey(e) {
    var b = buf();
    if (!b) {
      if (e.key === ':') { enterCommand(); return; }
      return;
    }
    var key = e.key;

    // Numeric prefix.
    if (key >= '0' && key <= '9' && (count !== '' || key !== '0')) {
      count += key;
      return;
    }
    var n = count ? parseInt(count) : 1;
    count = '';

    // Movement.
    if (key === 'h' || key === 'ArrowLeft') { b.cursor.col = Math.max(0, b.cursor.col - n); }
    else if (key === 'l' || key === 'ArrowRight') { b.cursor.col = Math.min(b.lines[b.cursor.row].length - 1, b.cursor.col + n); if (b.cursor.col < 0) b.cursor.col = 0; }
    else if (key === 'j' || key === 'ArrowDown') { b.cursor.row = Math.min(b.lines.length - 1, b.cursor.row + n); clampCol(b); }
    else if (key === 'k' || key === 'ArrowUp') { b.cursor.row = Math.max(0, b.cursor.row - n); clampCol(b); }
    else if (key === '0') { b.cursor.col = 0; }
    else if (key === '$') { b.cursor.col = Math.max(0, b.lines[b.cursor.row].length - 1); }
    else if (key === 'g') { b.cursor.row = 0; b.cursor.col = 0; }
    else if (key === 'G') { b.cursor.row = b.lines.length - 1; clampCol(b); }
    else if (key === 'w') { wordForward(b, n); }
    else if (key === 'b') { wordBackward(b, n); }
    // Scrolling.
    else if (e.ctrlKey && key === 'd') { b.cursor.row = Math.min(b.lines.length - 1, b.cursor.row + Math.floor(20 * n)); clampCol(b); }
    else if (e.ctrlKey && key === 'u') { b.cursor.row = Math.max(0, b.cursor.row - Math.floor(20 * n)); clampCol(b); }
    // Insert mode.
    else if (key === 'i') { mode = 'insert'; }
    else if (key === 'I') { b.cursor.col = 0; mode = 'insert'; }
    else if (key === 'a') { b.cursor.col = Math.min(b.lines[b.cursor.row].length, b.cursor.col + 1); mode = 'insert'; }
    else if (key === 'A') { b.cursor.col = b.lines[b.cursor.row].length; mode = 'insert'; }
    else if (key === 'o') { b.lines.splice(b.cursor.row + 1, 0, ''); b.cursor.row++; b.cursor.col = 0; b.modified = true; mode = 'insert'; }
    else if (key === 'O') { b.lines.splice(b.cursor.row, 0, ''); b.cursor.col = 0; b.modified = true; mode = 'insert'; }
    // Editing.
    else if (key === 'x') { for (var xi = 0; xi < n; xi++) delChar(b); }
    else if (key === 'd') { handleD(b, n); return; }  // wait for second key
    else if (key === 'y') { handleY(b, n); return; }
    else if (key === 'p') { paste(b, n); }
    else if (key === 'u') { setMsg('undo not yet implemented'); }
    else if (key === 'J') { joinLine(b); }
    // Search.
    else if (key === '/') { enterSearch(); return; }
    else if (key === 'n') { searchNext(b, 1); }
    else if (key === 'N') { searchNext(b, -1); }
    // Command.
    else if (key === ':') { enterCommand(); return; }

    render();
  }

  // dd = delete line, d$ = delete to end, etc.
  var pendingD = false;
  function handleD(b, n) {
    if (pendingD) { // dd
      pendingD = false;
      for (var i = 0; i < n; i++) {
        if (b.lines.length <= 1) { yankBuf = [b.lines[0]]; b.lines[0] = ''; break; }
        yankBuf = b.lines.splice(b.cursor.row, 1);
        if (b.cursor.row >= b.lines.length) b.cursor.row = b.lines.length - 1;
      }
      b.modified = true;
      clampCol(b);
      render();
      return;
    }
    pendingD = true;
    // Wait for next key — use a one-shot listener.
    var once = function(e2) {
      content.removeEventListener('keydown', once, true);
      e2.preventDefault();
      e2.stopPropagation();
      pendingD = false;
      if (e2.key === 'd') {
        // dd
        for (var i = 0; i < n; i++) {
          if (b.lines.length <= 1) { yankBuf = [b.lines[0]]; b.lines[0] = ''; break; }
          yankBuf = b.lines.splice(b.cursor.row, 1);
          if (b.cursor.row >= b.lines.length) b.cursor.row = b.lines.length - 1;
        }
        b.modified = true;
      } else if (e2.key === '$') {
        yankBuf = [b.lines[b.cursor.row].substring(b.cursor.col)];
        b.lines[b.cursor.row] = b.lines[b.cursor.row].substring(0, b.cursor.col);
        b.modified = true;
      } else if (e2.key === 'w') {
        // Delete word.
        var line = b.lines[b.cursor.row];
        var end = b.cursor.col;
        while (end < line.length && /\w/.test(line[end])) end++;
        while (end < line.length && /\s/.test(line[end])) end++;
        yankBuf = [line.substring(b.cursor.col, end)];
        b.lines[b.cursor.row] = line.substring(0, b.cursor.col) + line.substring(end);
        b.modified = true;
      }
      clampCol(b);
      render();
    };
    content.addEventListener('keydown', once, true);
  }

  var pendingY = false;
  function handleY(b, n) {
    var once = function(e2) {
      content.removeEventListener('keydown', once, true);
      e2.preventDefault();
      e2.stopPropagation();
      if (e2.key === 'y') {
        yankBuf = [];
        for (var i = 0; i < n; i++) {
          var r = b.cursor.row + i;
          if (r < b.lines.length) yankBuf.push(b.lines[r]);
        }
        setMsg(yankBuf.length + ' lines yanked');
      }
      render();
    };
    content.addEventListener('keydown', once, true);
  }

  function paste(b, n) {
    if (yankBuf.length === 0) return;
    for (var i = 0; i < n; i++) {
      if (yankBuf.length === 1 && yankBuf[0].indexOf('\n') < 0) {
        // Inline paste.
        var line = b.lines[b.cursor.row];
        b.lines[b.cursor.row] = line.substring(0, b.cursor.col + 1) + yankBuf[0] + line.substring(b.cursor.col + 1);
        b.cursor.col += yankBuf[0].length;
      } else {
        // Line paste below.
        for (var j = yankBuf.length - 1; j >= 0; j--) {
          b.lines.splice(b.cursor.row + 1, 0, yankBuf[j]);
        }
        b.cursor.row++;
      }
    }
    b.modified = true;
  }

  function delChar(b) {
    var line = b.lines[b.cursor.row];
    if (line.length === 0) return;
    b.lines[b.cursor.row] = line.substring(0, b.cursor.col) + line.substring(b.cursor.col + 1);
    clampCol(b);
    b.modified = true;
  }

  function joinLine(b) {
    if (b.cursor.row >= b.lines.length - 1) return;
    b.lines[b.cursor.row] += ' ' + b.lines[b.cursor.row + 1].trimStart();
    b.lines.splice(b.cursor.row + 1, 1);
    b.modified = true;
  }

  function insertKey(e) {
    var b = buf();
    if (!b) return;
    if (e.key === 'Escape') { mode = 'normal'; b.cursor.col = Math.max(0, b.cursor.col - 1); render(); return; }
    if (e.key === 'Backspace') {
      if (b.cursor.col > 0) {
        b.lines[b.cursor.row] = b.lines[b.cursor.row].substring(0, b.cursor.col - 1) + b.lines[b.cursor.row].substring(b.cursor.col);
        b.cursor.col--;
      } else if (b.cursor.row > 0) {
        var prevLen = b.lines[b.cursor.row - 1].length;
        b.lines[b.cursor.row - 1] += b.lines[b.cursor.row];
        b.lines.splice(b.cursor.row, 1);
        b.cursor.row--;
        b.cursor.col = prevLen;
      }
      b.modified = true;
      render();
      return;
    }
    if (e.key === 'Enter') {
      var line = b.lines[b.cursor.row];
      var before = line.substring(0, b.cursor.col);
      var after = line.substring(b.cursor.col);
      b.lines[b.cursor.row] = before;
      b.lines.splice(b.cursor.row + 1, 0, after);
      b.cursor.row++;
      b.cursor.col = 0;
      b.modified = true;
      render();
      return;
    }
    if (e.key === 'Tab') {
      insertChar(b, '  ');
      render();
      return;
    }
    if (e.key.length === 1 && !e.ctrlKey && !e.metaKey) {
      insertChar(b, e.key);
      render();
    }
  }

  function insertChar(b, ch) {
    var line = b.lines[b.cursor.row];
    b.lines[b.cursor.row] = line.substring(0, b.cursor.col) + ch + line.substring(b.cursor.col);
    b.cursor.col += ch.length;
    b.modified = true;
  }

  // --- Command mode ---
  function enterCommand() {
    mode = 'command';
    commandline.classList.remove('hidden');
    commandline.querySelector('.cmd-prefix').textContent = ':';
    cmdInput.value = '';
    cmdInput.focus();
    render();
  }

  function enterSearch() {
    mode = 'search';
    commandline.classList.remove('hidden');
    commandline.querySelector('.cmd-prefix').textContent = '/';
    cmdInput.value = '';
    cmdInput.focus();
    render();
  }

  function handleCmdKey(e) {
    if (e.key === 'Escape') { exitCommand(); return; }
    if (e.key === 'Enter') {
      var val = cmdInput.value.trim();
      exitCommand();
      if (mode === 'search' || commandline.querySelector('.cmd-prefix').textContent === '/') {
        searchTerm = val;
        searchNext(buf(), 1);
      } else {
        execCommand(val);
      }
      mode = 'normal';
      render();
      content.focus();
      return;
    }
  }

  function exitCommand() {
    mode = 'normal';
    commandline.classList.add('hidden');
    content.focus();
    render();
  }

  function execCommand(cmd) {
    var parts = cmd.split(/\s+/);
    var c = parts[0];
    if (c === 'w') { saveBuffer(); }
    else if (c === 'q') {
      if (buf() && buf().modified) { setMsg('unsaved changes (use :q! to force)'); }
      else { closeBuffer(activeIdx); }
    }
    else if (c === 'q!') { closeBuffer(activeIdx); }
    else if (c === 'wq') { saveBuffer(); setTimeout(function() { closeBuffer(activeIdx); }, 200); }
    else if (c === 'e' && parts[1]) { openBuffer(parts[1]); }
    else if (c === 'ls') {
      setMsg(buffers.map(function(b) { return b.id; }).join(', '));
    }
    else { setMsg('unknown command: ' + c); }
  }

  // --- Search ---
  function searchNext(b, dir) {
    if (!b || !searchTerm) return;
    var start = b.cursor.row + dir;
    for (var i = 0; i < b.lines.length; i++) {
      var r = (start + i * dir + b.lines.length) % b.lines.length;
      var idx = b.lines[r].toLowerCase().indexOf(searchTerm.toLowerCase());
      if (idx >= 0 && (r !== b.cursor.row || idx !== b.cursor.col)) {
        b.cursor.row = r;
        b.cursor.col = idx;
        render();
        return;
      }
    }
    setMsg('pattern not found: ' + searchTerm);
  }

  // --- Helpers ---
  function clampCol(b) {
    var maxCol = Math.max(0, b.lines[b.cursor.row].length - 1);
    if (mode === 'insert') maxCol = b.lines[b.cursor.row].length;
    b.cursor.col = Math.min(b.cursor.col, maxCol);
    if (b.cursor.col < 0) b.cursor.col = 0;
  }

  function wordForward(b, n) {
    for (var i = 0; i < n; i++) {
      var line = b.lines[b.cursor.row];
      var c = b.cursor.col;
      while (c < line.length && /\w/.test(line[c])) c++;
      while (c < line.length && /\s/.test(line[c])) c++;
      if (c >= line.length && b.cursor.row < b.lines.length - 1) {
        b.cursor.row++;
        b.cursor.col = 0;
      } else {
        b.cursor.col = Math.min(c, Math.max(0, line.length - 1));
      }
    }
  }

  function wordBackward(b, n) {
    for (var i = 0; i < n; i++) {
      var line = b.lines[b.cursor.row];
      var c = b.cursor.col - 1;
      if (c < 0 && b.cursor.row > 0) {
        b.cursor.row--;
        b.cursor.col = Math.max(0, b.lines[b.cursor.row].length - 1);
        continue;
      }
      while (c > 0 && /\s/.test(line[c])) c--;
      while (c > 0 && /\w/.test(line[c - 1])) c--;
      b.cursor.col = Math.max(0, c);
    }
  }

  function escHtml(s) {
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }
  function escRegex(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  init();
})();
"""
}

os/render/help/style.sl.content:
shape os.render.help.style {
  type: style
  layer: 4
  """
body {
  background: var(--bg, #1a1b26);
  color: var(--fg, #c0caf5);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  margin: 0;
  padding: 0;
}
#help-content {
  padding: 16px 20px;
}
#help-content h2 {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 8px 0;
  color: var(--accent, #7aa2f7);
}
#help-content h3 {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--fg-dim, #565f89);
  margin: 16px 0 6px 0;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--border, #292e42);
}
#help-content p {
  margin: 6px 0;
  line-height: 1.5;
}
.help-synopsis code {
  display: block;
  background: var(--bg-lighter, #24283b);
  padding: 8px 12px;
  border-radius: 4px;
  font-size: 12px;
  margin: 6px 0 10px 0;
  color: var(--green, #9ece6a);
}
.help-summary {
  color: var(--fg-dim, #565f89);
  font-style: italic;
  margin-bottom: 12px !important;
}
#help-content pre {
  background: var(--bg-lighter, #24283b);
  padding: 8px 12px;
  border-radius: 4px;
  font-size: 12px;
  overflow-x: auto;
  margin: 6px 0;
}
.help-see-also {
  margin-top: 16px;
  padding-top: 10px;
  border-top: 1px solid var(--border, #292e42);
  font-size: 12px;
}
.help-see-also a {
  color: var(--accent, #7aa2f7);
  text-decoration: none;
  margin-right: 8px;
}
.help-see-also a:hover { text-decoration: underline; }
"""
}

os/agent/tick_logger.sl.content:
shape os.agent.tick_logger : os.agent.registry {
  type: agent
  fn: agent.exec
